/* ------------------------------------------------- los archivos ----- */
/** Un numero como lo espera el Excel en castellano: coma decimal. */
const num2 = n => (Math.round(n*100)/100).toFixed(2).replace(".",",");
function bajarCSV(nombre, filas){
  const csv = filas.map(f=>f.map(c=>{
    const t = String(c==null ? "" : c);
    return /[;"\\r\\n]/.test(t) ? '"'+t.replace(/"/g,'""')+'"' : t;
  }).join(";")).join("\\r\\n");
  const blob = new Blob(["\\ufeff"+csv], {type:"text/csv;charset=utf-8"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = nombre;
  document.body.appendChild(a); a.click();
  setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); }, 500);
  toast("Bajó "+nombre+". Eso es lo que se adjunta al mail del contador.");
}
function sufijo(){
  const d = new Date();
  const f = d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
  return (S_FIL.conta ? sucDe(S_FIL.conta).n.replace(/[^A-Za-z]/g,"") : "TODAS")+"-"+f+".csv";
}
document.getElementById("bajadas").addEventListener("click",e=>{
  const b = e.target.closest("button[data-baja]"); if(!b) return;
  const vs = filtrar(S_FIL.conta);
  const ncs = S_FIL.conta ? NOTAS_CREDITO.filter(n=>n.suc===S_FIL.conta) : NOTAS_CREDITO;

  if(b.dataset.baja==="ventas"){
    const f = [["Fecha","Hora","Razon social","Punto de venta","Comprobante","Tipo","Facturada",
                "Vendedor","Forma de pago","Cliente","Neto","IVA","Total cobrado","Costo","Deja"]];
    for(const v of vs){
      const t = ventaCobrado(v);
      const co = v.linea.reduce((a,l)=>a+pdl(l).costo*l.cant,0);
      const c = clienteDeVenta(v);
      f.push([HOY, v.hora, sucDe(v.suc).n, sucDe(v.suc).pv, v.nro||"", v.facturada?("Factura "+v.letra):"Sin comprobante",
              v.facturada?"SI":"NO", v.vend, formaCorta(v.forma), c?c.n:"Consumidor final",
              num2(neto21(t)), num2(iva21(t)), num2(t), num2(co), num2(ventaBase(v)-co)]);
    }
    bajarCSV("ventas-"+sufijo(), f);

  } else if(b.dataset.baja==="iva"){
    const f = [["Fecha","Tipo","Punto de venta","Numero","Razon social","Cliente","CUIT/DNI",
                "Condicion IVA","Neto gravado","IVA 21%","Total"]];
    for(const v of vs.filter(x=>x.facturada)){
      const t = ventaCobrado(v), c = clienteDeVenta(v);
      f.push([HOY, "Factura "+v.letra, sucDe(v.suc).pv, v.nro, sucDe(v.suc).n,
              c?c.n:"Consumidor final", c?c.doc:"", c?c.t:"Consumidor Final",
              num2(neto21(t)), num2(iva21(t)), num2(t)]);
    }
    for(const n of ncs){
      f.push([HOY, "Nota de credito "+n.letra, sucDe(n.suc).pv, n.nro, sucDe(n.suc).n,
              "Anula "+n.anula, "", "", num2(-neto21(n.total)), num2(-iva21(n.total)), num2(-n.total)]);
    }
    bajarCSV("libro-iva-ventas-"+sufijo(), f);

  } else if(b.dataset.baja==="nc"){
    const f = [["Fecha","Comprobante","Razon social","Anula","Motivo","Neto","IVA 21%","Total"]];
    for(const n of ncs)
      f.push([HOY, n.nro, sucDe(n.suc).n, n.anula, n.motivo,
              num2(-neto21(n.total)), num2(-iva21(n.total)), num2(-n.total)]);
    bajarCSV("notas-de-credito-"+sufijo(), f);

  } else {
    const f = [["Fecha","Comprobante","Razon social","Codigo","Articulo","Rubro","Marca",
                "Cantidad","Precio unitario","Subtotal","Costo unitario"]];
    for(const v of vs.filter(x=>x.facturada)) for(const l of v.linea){
      const p = pdl(l);
      f.push([HOY, v.nro, sucDe(v.suc).n, p.cod, p.tit, p.rub, p.prov,
              l.cant, num2(p.contado), num2(p.contado*l.cant), num2(p.costo)]);
    }
    bajarCSV("detalle-por-articulo-"+sufijo(), f);
  }
});

/* ================================ LO EMITIDO QUEDA GUARDADO (V.0.99.78)
   Damián, 21/11/2026: "el presupuesto que emití, ¿dónde queda? deberían
   mostrarse todos los presupuestos y ver lo que estuve presupuestando o
   facturando" y "cuando refrescás no debería borrarse nada de lo que
   cargué".

   Dos lugares, según de quién es:
   - Lo EMITIDO (presupuestos, facturas, remitos, ventas sin comprobante) va
     al servidor (/sistema/documentos, src/lib/punto-documentos.ts). Lo
     ven todos los puestos, con el número que dio el servidor, y no se borra.
   - Lo que se está ARMANDO en esta compu (la venta empezada, los borradores,
     el pedido que se está tomando, los clientes y pedidos nuevos, quién
     vende y en qué sucursal) queda en el navegador (localStorage) y vuelve
     al recargar. Cada pestaña tiene lo suyo: dos pestañas no se pisan.
   El stock que mueve una venta todavía no se guarda: es la etapa siguiente. */
const DOCS_URL = "/sistema/documentos";
// var y no let: lo miran funciones que corren durante el arranque, antes de
// que esta línea se ejecute.
var EMITIENDO = false;

const horaAR = iso => new Date(iso).toLocaleTimeString("es-AR",
  { hour:"2-digit", minute:"2-digit", hour12:false, timeZone:"America/Argentina/Buenos_Aires" });
const fechaAR = iso => new Date(iso).toLocaleDateString("es-AR",
  { day:"2-digit", month:"2-digit", year:"2-digit", timeZone:"America/Argentina/Buenos_Aires" });

/** El comprobante con todo lo de este momento: si mañana cambia la lista,
    lo emitido hoy no cambia. */
function armarDocumento(comp, letra){
  const su = sucAct(), c = clienteVta(), dep = depAct();
  const renglones = S.linea.map(l => {
    const p = prod(l.cod), pl = precioLinea(p, l.cant);
    return { cod:p.cod, tit:p.tit, cant:l.cant, contado:pl.contado, unPago:pl.unPago,
             costo:p.costo, iva:ivaDe(p) };
  });
  const bruto = renglones.reduce((a, r) => a + r.contado * r.cant, 0);
  const descuento = Math.round(bruto * S.desc / 100);
  const total = (bruto - descuento) * MULT[S.forma];
  return {
    v:2, comp, letra, sucursal:su.id, pv:su.pv,
    // El número que mostraba la pantalla: el servidor usa ese o el que
    // sigue al último, el mayor de los dos. Nunca baja.
    desdeNumero: letra ? S.nro[su.id][letra] : 1, desdePedido: S.nroPed,
    vendedor:VENDEDOR_LOGIN || S.usuario, puesto:S.puesto,
    cliente: c ? { id:c.id, n:c.n, t:c.t, doc: letra === "A" && cuitDe(c) ? conGuiones(cuitDe(c)) : c.doc }
               : { id:"", n:"Consumidor final", t:"Consumidor Final", doc:"" },
    forma:S.forma, recargo:MULT[S.forma], desc:S.desc,
    deposito:dep, traida: dep !== su.dep,
    renglones, bruto, descuento, total,
    // Solo una venta queda unida al presupuesto. Volver a presupuestarlo no
    // lo da por vendido.
    origenId: letra !== "X" ? (S.origen || null) : null
  };
}

function firmaDe(doc){
  return JSON.stringify([doc.comp, doc.letra, doc.sucursal, doc.cliente.id, doc.forma,
    doc.desc, doc.deposito, doc.origenId, doc.edita ? doc.edita.id : "", doc.actualizaDe || "", doc.renglones.map(r => [r.cod, r.cant])]);
}
/** La marca de este comprobante para el servidor. Si el mismo se manda dos
    veces (doble clic, se cortó la conexión), vuelve el que ya estaba y no se
    gasta otro número. Si cambió lo que se emite, es otra marca. */
function marcaDe(doc){
  const firma = firmaDe(doc);
  if(!S.emision || S.emision.firma !== firma){
    const id = (window.crypto && crypto.randomUUID) ? crypto.randomUUID()
      : Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 12);
    S.emision = { firma, id, enviada:false };
  }
  return S.emision.id;
}

function botonesEmitir(trabados){
  for(const id of ["btnFactura","btnPresu","btnBorrador","btnSinFactura","btnCaja"]){
    const b = document.getElementById(id);
    if(b) b.disabled = trabados || !S.linea.length;
  }
}

/** ¿Quedó guardado el comprobante con esa marca? El documento, null (no
    está) o undefined (no se pudo saber: sin conexión). */
async function buscarPorMarca(id){
  try{
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), 10000);
    const r = await fetch(DOCS_URL + "?idLocal=" + encodeURIComponent(id),
      { cache:"no-store", credentials:"same-origin", signal:ctl.signal });
    clearTimeout(t);
    if(r.status === 401) return "sesion";
    const d = await r.json();
    if(!r.ok || d.error) return undefined;
    return d.documento || null;
  }catch(e){ return undefined; }
}
const AVISO_SESION = "Se cerró tu sesión: entrá de nuevo con tu usuario. La venta queda acá.";

/** Hay un comprobante que se mandó y no se sabe si quedó guardado. */
const pendiente = () => !!(S.emision && S.emision.enviada);
/** Mientras hay uno en duda, la venta no se mueve: ni a borrador, ni se vacía,
    ni se reemplaza. Si se moviera, la duda se perdería y al volver a emitir
    podría salir repetido. Lo único que se puede hacer es Emitir, que primero
    le pregunta al servidor. */
function trabadaPorDuda(){
  if(!pendiente()) return false;
  toast("Primero tocá Emitir: hay que confirmar si el comprobante anterior quedó guardado. Después seguís.");
  return true;
}

const esperar = ms => new Promise(r => setTimeout(r, ms));

/** Lo manda y devuelve {g, previo, igual}, o null (y lo dice).
    Tres respuestas posibles, y no son lo mismo:
    - guardado: vuelve el documento;
    - rechazado (vino un {error}): seguro que NO se guardó;
    - sin respuesta (se cortó, timeout, Cloudflare): PUEDE haberse guardado.
      Ahí se le pregunta al servidor por la marca antes de decir nada; decir
      "no se guardó" cuando sí se guardó terminaba en una factura repetida. */
async function emitirEnServidor(doc){
  EMITIENDO = true;
  botonesEmitir(true);
  try{
    // Quedó un envío sin respuesta (o se recargó en el medio): primero se
    // pregunta si ese se guardó, antes de mandar otro.
    if(S.emision && S.emision.enviada){
      const ya = await buscarPorMarca(S.emision.id);
      if(ya === "sesion"){ toast(AVISO_SESION); return null; }
      if(ya === undefined){
        toast("Todavía no sé si se guardó el comprobante anterior. Revisá la conexión y probá de nuevo.");
        return null;
      }
      if(ya) return { g:ya, previo:true, igual: S.emision.firma === firmaDe(doc) };
      S.emision = null;
    }
    // V.0.99.82: un ticket de caja que ya no está tomado por esta pantalla no
    // se emite (saldría sin atarlo al ticket, y el ticket lo cobraría otro);
    // uno se cobra en su caja (con otra sucursal salía con el CUIT y la
    // serie de otra); y la venta que volvió de la copia de esta compu espera
    // a saber cuál es en el servidor.
    if(doc.letra !== "X" && VSRV.caja && !VSRV.id){
      toast("Ese ticket ya no está tomado por vos: no lo emito. Fijate en Comprobantes, en «Pedidos por cobrar».");
      return null;
    }
    if(doc.letra !== "X" && VSRV.caja && VSRV.caja.suc && doc.sucursal !== VSRV.caja.suc){
      toast("Ese ticket es de la caja de " + sucDe(VSRV.caja.suc).n + ": se cobra con esa sucursal. Para pasarlo a otra, usá Mandar a caja.");
      return null;
    }
    if(PANTALLA_SRV && !VSRV.id){ toast("Esperá un segundo: estoy buscando en el servidor la venta de la pantalla."); return null; }
    doc.idLocal = marcaDe(doc);
    S.emision.enviada = true;
    guardarLocal();               // al toque: si se recarga ahora, la marca sobrevive
    // V.0.99.82: la venta del servidor de la que sale (la que se armaba, o el
    // ticket que tomó el cajero). El servidor la da por cobrada en la misma
    // operación que crea el comprobante: dos cajeros no cobran el mismo
    // ticket, y la comisión queda del vendedor.
    if(VSRV.id && doc.letra !== "X") doc.ventaId = VSRV.id;
    VSRV.cerrando = doc.ventaId || null;
    let d = null;
    for(let vuelta = 0; vuelta < 2; vuelta++){
    d = null;
    try{
      const ctl = new AbortController();
      const t = setTimeout(() => ctl.abort(), 30000);
      const r = await fetch(DOCS_URL, {
        method:"POST", credentials:"same-origin", signal:ctl.signal,
        headers:{ "Content-Type":"application/json" },
        // Si se está cambiando un presupuesto ya emitido, va aparte: el
        // servidor lo guarda con el mismo número.
        body: JSON.stringify(Object.assign({ documento: doc, yo: soyYo() }, doc.edita ? { edita: doc.edita } : {}))
      });
      clearTimeout(t);
      d = await r.json().catch(() => null);
    }catch(e){ d = null; }
    // La venta que se armaba ya no está en el servidor (se vació en otra
    // pestaña, se cortó el guardado): se emite sin atarla. Un ticket de caja
    // no: ese tiene que estar tomado por el que cobra.
    if(d && d.error && doc.ventaId && !VSRV.caja && /ya no está en el servidor/.test(d.error)){
      delete doc.ventaId; VSRV.id = null; VSRV.version = null; continue;
    }
    break;
    }
    if(d && d.documento){ ponerStockServidor(d.stock); return { g:d.documento, previo:false, igual:true }; }
    if(d && d.error){
      S.emision.enviada = false; guardarLocal();
      toast("No se guardó: " + d.error + " La venta sigue acá: probá de nuevo.");
      return null;
    }
    toast("Se cortó la respuesta. Me fijo si quedó guardado…");
    for(const ms of [1000, 2500, 5000]){
      await esperar(ms);
      const ya = await buscarPorMarca(doc.idLocal);
      if(ya === "sesion"){ toast(AVISO_SESION); return null; }
      if(ya) return { g:ya, previo:false, igual:true };
      if(ya === null){
        S.emision.enviada = false; guardarLocal();
        toast("No se guardó: se cortó la conexión. La venta sigue acá: probá de nuevo.");
        return null;
      }
    }
    toast("No pude saber si se guardó. No cambies la venta y tocá Emitir de nuevo: si ya estaba guardado, no se repite.");
    return null;
  }finally{
    EMITIENDO = false;
    botonesEmitir(false);
  }
}

function numerosDe(g){
  const n = { pedido: g.pedido };
  if(g.letra && g.numero) n[g.sucursal + ":" + g.letra] = g.numero;
  return n;
}

/** Lo emitido pasa a la venta del día con lo que valía en ese momento. */
function ventaDeDocumento(g){
  const dt = g.datos || {}, ren = dt.renglones || [], cli = dt.cliente || {};
  const facturada = g.letra === "A" || g.letra === "B";
  return {
    hora: horaAR(g.createdAt), suc: g.sucursal, puesto: sinEtiquetas(g.puesto), vend: sinEtiquetas(g.vendedor),
    forma: MULT[dt.forma] ? dt.forma : "01-Efectivo",
    // Solo la factura va al libro. Un remito o un pedido interno tienen
    // número, pero no son facturas (antes entraban al Libro IVA).
    facturada, web:false, ped: "P-" + g.pedido,
    dep: dt.deposito === "TS" ? "TS" : "BA", traida: !!dt.traida,
    linea: lineasDeDocumento(g),
    // Lo cobrado ya trae el descuento: la base y el margen tambien.
    base: (+dt.bruto || 0) - (+dt.descuento || 0), descPesos: +dt.descuento || 0,
    letra: facturada ? g.letra : undefined, nro: g.nroTexto,
    cli: cli.id || "", cliN: sinEtiquetas(cli.n || ""), cliT: sinEtiquetas(cli.t || ""), cliDoc: sinEtiquetas(cli.doc || ""),
    total: g.total, comp: g.comp, docId: g.id, _doc: g, nd: g.tipo === "nota-debito"
  };
}
/** Los renglones que la pantalla puede mostrar: los de artículos que hoy
    están en el catálogo. Si GBP carga tarde, se vuelven a armar. */
function lineasDeDocumento(g){
  // Todos los renglones, aunque el artículo no esté en el catálogo de esta
  // compu: pdl() los completa con lo guardado. Si se tiraran, el margen
  // saldría mal (el total y el descuento son de todos).
  return ((g.datos && g.datos.renglones) || [])
    .map(r => ({ cod:r.cod, cant:+r.cant || 0, contado:+r.contado || 0, costo:+r.costo || 0, tit:sinEtiquetas(r.tit) }));
}
/** El artículo de un renglón de venta, para los informes: el del catálogo,
    con el precio y el costo que valían al venderlo si la venta los guardó.
    Si el artículo no está en el catálogo, lo guardado. */
function pdl(l){
  const p = prod(l.cod);
  if(l.contado == null) return p;
  return Object.assign({ cod:l.cod, tit:l.tit || l.cod, rub:"OTROS", prov:"VARIOS", unPago:l.contado },
    p || {}, { contado:l.contado, costo:l.costo != null ? l.costo : (p ? p.costo : 0) });
}
function remapearVentasDeHoy(){
  for(const v of S.ventas) if(v._doc) v.linea = lineasDeDocumento(v._doc);
}

/** El cliente de una venta para el Libro IVA: el de la lista, o el que
    quedó guardado con el comprobante (de un cliente cargado en otra compu). */
function clienteDeVenta(v){
  const c = v.cli ? CLIENTES.find(x => x.id === v.cli) : null;
  if(c) return c;
  if(v.cliN && v.cliN !== "Consumidor final")
    return { n:v.cliN, doc:v.cliDoc || "—", t:v.cliT || "Consumidor Final" };
  return null;
}

/** Lo que pasa en la pantalla cuando un comprobante quedó guardado. */
function registrarEmitido(g){
  const dt = g.datos || {};
  if(g.tipo !== "presupuesto"){
    if(!g.eliminado && !S.ventas.some(v => v.docId === g.id)){
      // El stock lo descuenta el servidor y vuelve con la respuesta
      // (ponerStockServidor, V.0.99.94).
      S.ventas.push(ventaDeDocumento(g));
    }
  } else if(!fueCambio(g)){
    S.presupuestos++;
    S.presuDe[g.vendedor] = (S.presuDe[g.vendedor] || 0) + 1;
  }
  if(fueCambio(g) && S.editando && S.editando.id === g.id)
    S.editando.base = +g.datos.ed || S.editando.base;
  // La serie de este comprobante queda en el que sigue al que dio el
  // servidor (si recortó un salto grande, la pantalla no sigue mostrando el
  // número tipeado). Las otras series y el pedido, solo suben.
  // Un presupuesto cambiado conserva su número viejo: la serie no se toca.
  if(!fueCambio(g) && g.letra && g.numero && S.nro[g.sucursal] && S.nro[g.sucursal][g.letra] != null)
    S.nro[g.sucursal][g.letra] = g.numero + 1;
  sincronizarNumeros(numerosDe(g));
}
/** Un presupuesto ya emitido que se cambió (no uno nuevo). */
const fueCambio = g => g.tipo === "presupuesto" && !!(g.datos && g.datos.editado);
/** V.0.99.98: lo que autorizó ARCA, para decirlo al emitir. */
const conCaeTxt = g => { const a = (g.datos || {}).arca; return a && a.cae ? " Autorizada por ARCA: CAE " + a.cae + "." : ""; };
function textoEmitido(g){
  const dt = g.datos || {}, su = sucDe(g.sucursal);
  if((dt.arca || {}).cae && g.tipo === "factura")
    return g.comp.replace(/^\\d+\\./, "") + " " + g.nroTexto.slice(2) + " de " + su.n + " por " + fmt(g.total) + "." + conCaeTxt(g) +
      " Sale del depósito de " + (DEPOSITOS[dt.deposito] || dt.deposito) + ". En Comprobantes la bajás en PDF o se la mandás por WhatsApp.";
  if(fueCambio(g))
    return "Presupuesto " + g.nroTexto.slice(2) + " de " + su.n + " cambiado, por " + fmt(g.total) +
      ". Sigue con el mismo número y lo de antes quedó guardado. En Comprobantes lo bajás en PDF.";
  const nombre = g.comp.replace(/^\\d+\\./, "");
  const deDonde = "Sale del depósito de " + (DEPOSITOS[dt.deposito] || dt.deposito) +
    (dt.traida ? ", que hay que traer a " + su.n : "") + ".";
  if(g.tipo === "presupuesto")
    return "Presupuesto " + g.nroTexto.slice(2) + " de " + su.n + " guardado, por " + fmt(g.total) +
      ". Lo ves en Comprobantes: de ahí lo bajás en PDF, lo imprimís o lo pasás a venta. No mueve stock ni caja.";
  if(g.tipo === "sin-comprobante")
    return "Entregado sin comprobante por " + fmt(g.total) + " en " + su.n + ", P-" + g.pedido +
      ". Quedó guardado y marcado como tal. " + deDonde;
  if(g.tipo === "factura")
    return nombre + " " + g.nroTexto.slice(2) + " guardada, por " + fmt(g.total) +
      ". Es interna: todavía no va a ARCA (sin CAE). La ves en Comprobantes. " + deDonde;
  return nombre + " " + g.nroTexto.slice(2) + " guardado, por " + fmt(g.total) + ". La ves en Comprobantes. " + deDonde;
}
/** Después de emitir: se anota y se limpia la venta. Si lo que volvió es un
    envío anterior que sí se había guardado y la venta de la pantalla cambió
    desde entonces, la venta NO se limpia: se avisa y se decide. */
function trasEmitir(res){
  if(!res) return;
  const g = res.g;
  registrarEmitido(g);
  if(res.previo && !res.igual){
    S.emision = null; guardarLocal();
    VSRV.id = null; VSRV.version = null; VSRV.caja = null; VSRV.ultimo = ""; pintarCajaTicket();
    toast("Ojo: el comprobante anterior SÍ se había guardado (" + g.comp.replace(/^\\d+\\./, "") + " " +
      (g.letra ? g.nroTexto.slice(2) : "P-" + g.pedido) + ", " + fmt(g.total) + "). " +
      "La venta de la pantalla tiene cambios y queda acá: si también va, emitila de nuevo.");
    pintarTicket();
    return;
  }
  limpiarVentaEmitida();
  toast((res.previo ? "Ya había quedado guardado. " : "") + textoEmitido(g));
}

function limpiarVentaEmitida(){
  S.linea = []; S.desc = 0; S.lista = 2; S.comp = null; S.dep = null; S.nroLibre = false;
  S.origen = null; S.emision = null; terminarEdicion();
  // El ticket de caja ya se cobró (o se mandó, o se devolvió).
  VSRV.caja = null; pintarCajaTicket();
  // Lo emitido cerró la venta del servidor (iba con ventaId): ya no es de
  // esta pantalla. Si quedaba atada y el guardado vacío fallaba, la venta
  // nueva siguiente chocaba con la cobrada.
  if(VSRV.cerrando && VSRV.cerrando === VSRV.id){ VSRV.id = null; VSRV.version = null; VSRV.ultimo = ""; }
  VSRV.cerrando = null;
  pintarCamposVenta(); pintarDtos(); pintarTicket();
  guardarLocal();                 // al toque: que no vuelva al recargar
  asegurarGuardada();             // y en el servidor tampoco
  // El cursor al buscador para la venta que sigue. En el body, el Enter
  // sumaría el primero marcado (la trampa de #camposVta).
  const q = document.getElementById("q");
  q.value = ""; buscar(); q.focus();
}

/** Repinta el comprobante sin dejar el foco en el body (ver la trampa de
    #camposVta en pintarCamposVenta). */
function repintarVentaConFoco(){
  const a = document.activeElement, id = a && a.id;
  pintarCamposVenta();
  if(id){ const e = document.getElementById(id); if(e && e !== document.activeElement) e.focus(); }
}

/** Los números que vienen del servidor (el último usado de cada serie):
    la pantalla muestra el que sigue. Solo suben. */
function sincronizarNumeros(cont){
  let cambio = false;
  for(const k of Object.keys(cont || {})){
    const ult = +cont[k];
    if(!(ult > 0)) continue;
    if(k === "pedido"){ if(S.nroPed < ult + 1){ S.nroPed = ult + 1; cambio = true; } continue; }
    const par = k.split(":"), suc = par[0], l = par[1];
    if(S.nro[suc] && S.nro[suc][l] != null && S.nro[suc][l] < ult + 1){ S.nro[suc][l] = ult + 1; cambio = true; }
  }
  // Si está corrigiendo el número a mano, no se lo cambio debajo.
  if(cambio && !S.nroLibre) repintarVentaConFoco();
}

/** Lo emitido hoy vuelve a la Caja, la Rentabilidad y el Contable al
    recargar. */
async function traerDocumentosDeHoy(){
  try{
    const r = await fetch(DOCS_URL + "?dias=1", { cache:"no-store", credentials:"same-origin" });
    if(!r.ok) return;
    const d = await r.json();
    if(d.error) return;
    if(d.contadores) sincronizarNumeros(d.contadores);
    const ya = new Set(S.ventas.filter(v => v.docId).map(v => v.docId));
    let n = 0;
    for(const g of (d.documentos || []).slice().reverse()){
      if(g.tipo === "presupuesto" || ya.has(g.id)) continue;
      if(g.tipo === "nota-credito"){ sumarNota(g); continue; }
      S.ventas.push(ventaDeDocumento(g));
      n++;
    }
    if(n) repintarInformes();
  }catch(e){ /* sin conexión: queda lo de esta sesión */ }
}
function repintarInformes(){
  const v = vistaActual();
  if(v === "caja") pintarCaja();
  if(v === "contable") pintarContable();
  if(v === "renta") pintarRenta();
  if(v === "gerencia") pintarGerencia();
}

/* ------------------------------------------------ COMPROBANTES (la vista) */
const CP = { docs:[], hayMas:false, cargando:false, error:"", abierto:null, pedido:0 };
const NOMBRE_TIPO = { "presupuesto":"Presupuesto", "factura":"Factura", "remito":"Remito",
                      "pedido-interno":"Pedido interno", "sin-comprobante":"Sin comprobante",
                      "nota-credito":"Nota de crédito", "nota-debito":"Nota de débito" };

document.getElementById("cpSuc").innerHTML = '<option value="">Las tres sucursales</option>' +
  SUCURSALES.map(x => '<option value="' + x.id + '">' + x.n + '</option>').join("");

async function pintarComprobantes(){
  const dias = +document.getElementById("cpDias").value || 30;
  const tipo = document.getElementById("cpTipo").value;
  const suc = document.getElementById("cpSuc").value;
  // Si se cambia un filtro mientras viaja el anterior, gana el último.
  const este = ++CP.pedido;
  CP.cargando = true; pintarListaCp();
  try{
    const q = new URLSearchParams({ dias:String(dias) });
    if(tipo && tipo !== "preparacion") q.set("tipo", tipo);
    if(suc) q.set("suc", suc);
    const r = await fetch(DOCS_URL + "?" + q.toString(), { cache:"no-store", credentials:"same-origin" });
    const d = await r.json().catch(() => ({ error:"El servidor contestó " + r.status + "." }));
    if(este !== CP.pedido) return;
    if(!r.ok || d.error) throw new Error(d.error || "No se pudo leer.");
    CP.docs = d.documentos || []; CP.hayMas = !!d.hayMas; CP.error = "";
    // En preparación: lo emitido (no presupuestos) que todavía nadie despachó.
    if(tipo === "preparacion") CP.docs = CP.docs.filter(x => x && x.tipo !== "presupuesto" && !(x.datos && x.datos.despacho));
    if(d.contadores) sincronizarNumeros(d.contadores);
  }catch(e){
    if(este !== CP.pedido) return;
    CP.docs = []; CP.error = e.message || "No se pudo leer.";
  }
  CP.cargando = false;
  pintarListaCp();
}

function nombreDoc(g){
  const t = NOMBRE_TIPO[g.tipo] || g.tipo;
  return g.tipo === "factura" ? t + " " + g.letra : t;
}
// "B 0003-00048214" -> "0003-00048214"; "P-2850" queda igual.
const numeroCorto = g => String(g.nroTexto || "").replace(/^[A-Z] /, "");

function pintarListaCp(){
  const tb = document.getElementById("tbCp"), cuenta = document.getElementById("cpCount");
  const tbP = document.getElementById("tbPresu"), cuentaP = document.getElementById("cpCountPresu");
  const vacio = t => '<tr><td colspan="6" class="vacio">' + t + '</td></tr>';
  if(CP.cargando && !CP.docs.length){ tb.innerHTML = tbP.innerHTML = vacio("Buscando…"); return; }
  if(CP.error){ tb.innerHTML = tbP.innerHTML = vacio(txt(CP.error)); cuenta.textContent = cuentaP.textContent = ""; return; }
  const toks = plano(document.getElementById("cpBusca").value).split(/\\s+/).filter(Boolean);
  const porId = {};
  for(const d of CP.docs) porId[d.id] = d;
  const lista = CP.docs.filter(d => {
    if(!toks.length) return true;
    const ren = (d.datos && d.datos.renglones) || [];
    const t = plano(d.nroTexto + " p-" + d.pedido + " " + d.cliente + " " + d.vendedor + " " + d.usuario + " " +
      nombreDoc(d) + " " + ren.map(r => r.cod + " " + r.tit).join(" "));
    return toks.every(x => t.indexOf(x) >= 0);
  });
  const suma = tipo => lista.filter(d => d.tipo === tipo && !d.eliminado).reduce((a, d) => a + d.total, 0);
  // V.0.100.1: los presupuestos van en su propia lista, abajo.
  const comps = lista.filter(d => d.tipo !== "presupuesto"), presus = lista.filter(d => d.tipo === "presupuesto");
  cuenta.textContent = comps.length + (comps.length === 1 ? " comprobante" : " comprobantes") +
    (lista.some(d => d.tipo === "factura") ? " · facturado " + fmt(suma("factura")) : "") +
    (lista.some(d => d.tipo === "sin-comprobante") ? " · sin comprobante " + fmt(suma("sin-comprobante")) : "") +
    (lista.some(d => d.tipo === "nota-credito") ? " · notas de crédito " + fmt(suma("nota-credito")) : "") +
    (CP.hayMas ? " · se ven los últimos 500" : "");
  cuentaP.textContent = presus.length + (presus.length === 1 ? " presupuesto" : " presupuestos") +
    (presus.length ? " · presupuestado " + fmt(suma("presupuesto")) : "");
  // Con el filtro en "Presupuestos" no se ve la lista de comprobantes, y al revés.
  const ft = document.getElementById("cpTipo").value;
  tb.closest(".card").hidden = ft === "presupuesto";
  document.getElementById("cardPresu").hidden = !!ft && ft !== "presupuesto" && ft !== "eliminados";
  const nada = CP.docs.length ? "Nada coincide con lo que buscás." : "Todavía no hay nada en este período.";
  const filaCp = d => {
    const dt = d.datos || {}, cli = dt.cliente || {};
    // Si se vendió lo dice el servidor, aparte de los filtros de la lista.
    const vendido = d.tipo === "presupuesto" ? d.vendidoEn : null;
    const madre = d.origenId ? porId[d.origenId] : null;
    const pills =
      (d.tipo === "factura" || d.tipo === "nota-credito" || d.tipo === "nota-debito"
        ? (((d.datos || {}).arca || {}).cae ? ' <span class="pill p-ok" title="Autorizada por ARCA">CAE</span>' : ' <span class="pill p-warn">sin CAE</span>')
        : "") +
      (vendido ? ' <span class="pill p-ok">vendido · ' + txt(vendido.comp.replace(/^\\d+\\./, "")) + ' ' + txt(numeroCorto(vendido)) + '</span>' : "") +
      (d.origenId ? ' <span class="pill p-n">de presupuesto' + (madre ? " " + txt(numeroCorto(madre)) : "") + '</span>' : "") +
      (dt.editado ? ' <span class="pill p-n">cambiado</span>' : "") +
      (d.actualizadoEn ? ' <span class="pill p-n">actualizado en ' + txt(numeroCorto(d.actualizadoEn)) + '</span>' : "") +
      (dt.actualizaDe ? ' <span class="pill p-n">actualiza ' + (porId[dt.actualizaDe] ? "al " + txt(numeroCorto(porId[dt.actualizaDe])) : "a uno anterior") + '</span>' : "") +
      (d.eliminado ? ' <span class="pill p-bad">eliminado</span>' : "");
    const abierto = CP.abierto === d.id;
    let h = '<tr class="cp-fila' + (abierto ? " cp-abierta" : "") + (d.eliminado ? " cp-elim" : "") + '" data-cp="' + txt(d.id) + '">' +
      '<td class="num" style="font-size:12.5px">' + fechaAR(d.createdAt) + '<small>' + horaAR(d.createdAt) + '</small></td>' +
      '<td><b>' + txt(nombreDoc(d)) + '</b> ' + txt(d.letra ? numeroCorto(d) : "") + pills +
        '<small>P-' + d.pedido + ' · ' + txt(sucDe(d.sucursal).n) + '</small></td>' +
      '<td>' + txt(d.cliente) + (cli.doc && cli.doc !== "—" ? '<small>' + txt(cli.doc) + '</small>' : "") + '</td>' +
      '<td>' + txt(d.vendedor) + quienesCp(d) + '</td>' +
      '<td class="r" style="font-weight:600">' + fmt(d.total) + '</td>' +
      '<td class="r cp-acc">' + accionesCp(d, vendido) + '</td>' +
    '</tr>';
    if(abierto){
      const ren = dt.renglones || [];
      h += '<tr class="cp-det"><td colspan="6"><table class="densa"><thead><tr>' +
        '<th>Código</th><th>Artículo</th><th class="r">Cant.</th><th class="r">Precio</th><th class="r">Subtotal</th>' +
        '</tr></thead><tbody>' + ren.map(r =>
          '<tr><td class="num">' + txt(r.cod) + '</td><td>' + txt(r.tit) + '</td><td class="r">' + (+r.cant || 0) + '</td>' +
          '<td class="r">' + fmt(+r.contado || 0) + '</td><td class="r">' + fmt((+r.contado || 0) * (+r.cant || 0)) + '</td></tr>').join("") +
        '</tbody></table><div class="cp-mas">' +
        'Forma de pago: ' + txt(formaCorta(dt.forma || "")) +
        (dt.desc ? ' · descuento ' + (+dt.desc) + '% (' + fmt(+dt.descuento || 0) + ')' : '') +
        (dt.recargo && dt.recargo !== 1 ? ' · recargo de tarjeta ' + pTxt(Math.round((dt.recargo - 1) * 1000) / 10) + '%' : '') +
        ' · depósito ' + txt(DEPOSITOS[dt.deposito] || dt.deposito || "") + (dt.traida ? ' (se trae)' : '') +
        ' · vendió ' + txt(d.vendedor) + (d.tipo !== "presupuesto" ? ' · cobró ' + txt(d.cobroNombre || d.usuario) : ' · lo hizo ' + txt(d.cobroNombre || d.usuario)) +
        (dt.despacho ? ' · despachó ' + txt(dt.despacho.nombre || dt.despacho.por) + ' el ' + fechaAR(dt.despacho.en) + ' a las ' + horaAR(dt.despacho.en) +
          (dt.despacho.nota ? ' (' + txt(dt.despacho.nota) + ')' : '') : '') +
        (cli.t ? ' · cliente ' + txt(cli.t) : '') +
        (dt.editado ? ' · cambiado ' + (+dt.editado.veces || 1) + ((+dt.editado.veces || 1) > 1 ? ' veces' : ' vez') +
          ', la última el ' + fechaAR(dt.editado.en) + ' a las ' + horaAR(dt.editado.en) + ' por ' + txt(dt.editado.por) : '') +
        (d.eliminado ? ' · <b style="color:var(--bad)">eliminado el ' + fechaAR(d.eliminado.en) + ' a las ' + horaAR(d.eliminado.en) +
          ' por ' + txt(d.eliminado.por) + '</b>' : '') +
        '</div></td></tr>';
    }
    return h;
  };
  tb.innerHTML = comps.length ? comps.map(filaCp).join("") : vacio(nada);
  tbP.innerHTML = presus.length ? presus.map(filaCp).join("") : vacio(nada);
}

/* Los clics de las dos listas (Comprobantes y Presupuestos), en un solo lugar. */
function clicCp(e){
  const b = e.target.closest("[data-pasar]");
  if(b){ const d = CP.docs.find(x => x.id === b.dataset.pasar); if(d) pasarAVenta(d); return; }
  const acc = e.target.closest("[data-acc]");
  if(acc){
    const d = CP.docs.find(x => x.id === acc.dataset.id);
    if(!d) return;
    const a = acc.dataset.acc;
    if(a === "editar") editarPresu(d);
    if(a === "actualizar") actualizarPresu(d);
    if(a === "pdf") traerPdf(d, acc, false);
    if(a === "whats") mandarPorWhats(d);
    if(a === "imprimir") traerPdf(d, acc, true);
    if(a === "eliminar") eliminarDoc(d, acc, false);
    if(a === "recuperar") eliminarDoc(d, acc, true);
    if(a === "despachar") despacharDoc(d, acc, false);
    if(a === "nodespachar") despacharDoc(d, acc, true);
    if(a === "nc") abrirNota(d, "credito");
    if(a === "nd") abrirNota(d, "debito");
    return;
  }
  const f = e.target.closest("tr[data-cp]");
  if(!f) return;
  CP.abierto = CP.abierto === f.dataset.cp ? null : f.dataset.cp;
  pintarListaCp();
}
for(const id of ["tbCp","tbPresu"]) document.getElementById(id).addEventListener("click", clicCp);
for(const id of ["cpTipo","cpSuc","cpDias"])
  document.getElementById(id).addEventListener("change", () => { CP.abierto = null; pintarComprobantes(); });
document.getElementById("cpBusca").addEventListener("input", pintarListaCp);
// Nuevo comprobante: la venta en blanco. Si había una empezada, se ofrece
// guardarla como borrador (no se pierde).
document.getElementById("cpNuevo").addEventListener("click", () => {
  if(EMITIENDO){ toast("Esperá un segundo: se está guardando un comprobante."); return; }
  if(S.linea.length){
    if(trabadaPorDuda()) return;
    if(confirm("Hay una venta empezada. ¿La guardo como borrador y arranco una nueva?"))
      document.getElementById("btnBorrador").click();
  }
  abrirVista("mostrador");
  const q = document.getElementById("q");
  q.value = ""; buscar(); q.focus();
});

/** Los botones de cada renglón de Comprobantes. Damián, 22/11/2026: "esto
    si fue emitido tendria que bajar el pdf o dejarme editarlo" y "ahi
    tambien debes dar la posiblidad de imprimir, eliminar". */
function accionesCp(d, vendido){
  const id = txt(d.id);
  const bt = (acc, texto, clase, titulo) => '<button class="' + (clase || "b2") + '" type="button" data-acc="' + acc +
    '" data-id="' + id + '"' + (titulo ? ' title="' + titulo + '"' : '') + '>' + texto + '</button>';
  if(d.eliminado) return bt("pdf", "PDF") + (puede("eliminar") ? bt("recuperar", "Recuperar", "b2", "Vuelve a la lista y a la Caja") : "");
  const whats = bt("whats", "WhatsApp", "b2", "Mandarle al cliente el detalle con el link al PDF");
  const presuLibre = d.tipo === "presupuesto" && !vendido && puede("venta");
  return (presuLibre ? bt("editar", "Editar", "b2", "Cambiarlo: queda con el mismo número") +
      '<button class="b2" type="button" data-pasar="' + id + '">Pasar a venta</button>' : "") +
    bt("pdf", "PDF", "b2", "Bajar el PDF") + whats +
    bt("imprimir", "Imprimir", "b2") +
    (d.tipo === "presupuesto" && puede("venta") ? bt("actualizar", "Precios de hoy", "b2", "Hace un presupuesto nuevo con los precios de hoy; este queda como está") : "") +
    (d.tipo !== "presupuesto" && d.tipo !== "nota-credito" && d.tipo !== "nota-debito" && puede("despachar")
      ? ((d.datos || {}).despacho
          ? (((d.datos.despacho.por === soyYo()) || esAdminUsuarios()) ? bt("nodespachar", "Deshacer despacho", "b3", "Si se marcó por error") : "")
          : bt("despachar", "Despachado", "b2", "Anota que la mercadería salió del depósito y quién la entregó"))
      : "") +
    (d.tipo === "factura" && (d.letra === "A" || d.letra === "B") && puede("cobrar")
      ? bt("nc", "Nota de crédito", "b2", "Devuelve artículos de esta factura: vuelven al stock") +
        bt("nd", "Nota de débito", "b2", "Le suma un monto a esta factura (interés, diferencia de precio...)")
      : "") +
    (puede("eliminar") && !((d.datos || {}).arca || {}).cae ? bt("eliminar", "Eliminar", "b3", "Sale de la lista y de la Caja; se puede recuperar") : "");
}
/* V.0.99.96: la nota de crédito o de débito de una factura A o B. La de
   crédito devuelve artículos (vuelven al stock del depósito de la factura);
   la de débito suma un monto. Las dos internas, como la factura: sin CAE. */
function abrirNota(d, clase){
  if(document.getElementById("notaFondo")) return;
  const dt = d.datos || {}, ren = dt.renglones || [];
  const nc = clase === "credito";
  const idLocal = (window.crypto && crypto.randomUUID) ? crypto.randomUUID()
    : Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 12);
  const cuerpo = nc
    ? '<p class="nota" style="margin:0 0 8px">Cuántos de cada artículo devuelve. Lo devuelto vuelve al stock de '+(dt.deposito === "TS" ? "Traslasierra" : "Buenos Aires")+'.</p>'+
      '<div class="tabla-wrap"><table class="densa"><thead><tr><th>Artículo</th><th class="r">Facturado</th><th class="r">Devuelve</th></tr></thead><tbody>'+
      ren.map((r, i) => '<tr><td><span class="num">'+txt(r.cod)+'</span> '+txt(String(r.tit || "").slice(0, 46))+'</td><td class="r">'+(+r.cant || 0)+'</td>'+
        '<td class="r"><input type="number" min="0" max="'+(+r.cant || 0)+'" step="1" value="'+(+r.cant || 0)+'" data-nc="'+i+'" style="width:72px"></td></tr>').join("")+
      '</tbody></table></div>'
    : '<label style="display:block">Monto con IVA <input id="ndMonto" type="text" inputmode="decimal" placeholder="0,00" autocomplete="off" style="width:100%"></label>';
  document.body.insertAdjacentHTML("beforeend",
    '<div id="notaFondo" style="position:fixed;inset:0;background:rgba(20,20,20,.38);z-index:2000;display:flex;align-items:center;justify-content:center;padding:16px">'+
    '<div class="card" style="max-width:660px;width:100%;max-height:90vh;overflow:auto;padding:18px">'+
    '<h3 style="margin:0 0 2px">'+(nc ? "Nota de crédito " : "Nota de débito ")+txt(d.letra)+'</h3>'+
    '<div class="por" style="margin-bottom:12px">De la factura '+txt(d.nroTexto)+' · '+txt(d.cliente)+' · '+fmt(d.total)+'</div>'+cuerpo+
    '<label style="display:block;margin-top:10px">Motivo <input id="notaMotivo" type="text" maxlength="200" autocomplete="off" style="width:100%" placeholder="'+
      (nc ? "Devolución, cambio, error en la factura..." : "Interés, diferencia de precio...")+'"></label>'+
    '<div id="notaTotal" class="por" style="margin-top:8px"></div>'+
    '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px">'+
      '<button class="b2" type="button" id="notaCancelar">Cancelar</button>'+
      '<button class="b1" type="button" id="notaHacer">'+(nc ? "Hacer la nota de crédito" : "Hacer la nota de débito")+'</button></div></div></div>');
  const fondo = document.getElementById("notaFondo");
  const cants = () => ren.map((r, i) => { const e = fondo.querySelector('[data-nc="'+i+'"]'); return e ? Math.max(0, Math.min(+r.cant || 0, Math.floor(+e.value || 0))) : 0; });
  const cuenta = () => {
    if(!nc){ const m = aNum(document.getElementById("ndMonto").value); document.getElementById("notaTotal").textContent = m > 0 ? "Total de la nota: " + fmt(m) : ""; return; }
    const c = cants();
    const peso = cs => ren.reduce((a, r, i) => a + (+r.contado || 0) * cs[i], 0);
    const todo = peso(ren.map(r => +r.cant || 0));
    const t = todo > 0 ? Math.round(d.total * peso(c) / todo * 100) / 100 : 0;
    document.getElementById("notaTotal").textContent = "Total de la nota: aprox. " + fmt(t) + " (lo calcula el servidor con lo que ya se devolvió de esta factura).";
  };
  fondo.addEventListener("input", cuenta);
  cuenta();
  const cerrar = () => fondo.remove();
  document.getElementById("notaCancelar").addEventListener("click", cerrar);
  fondo.addEventListener("click", e => { if(e.target === fondo) cerrar(); });
  document.getElementById("notaHacer").addEventListener("click", async e => {
    const b = e.currentTarget;
    const motivo = document.getElementById("notaMotivo").value.replace(/[<>]/g, "").trim();
    const cuerpoPost = { facturaId: d.id, clase, idLocal, motivo, puesto: S.puesto, yo: soyYo() };
    if(nc){ cuerpoPost.cants = cants(); if(!cuerpoPost.cants.some(x => x > 0)){ toast("Marcá cuántos de cada artículo se devuelven."); return; } }
    else {
      cuerpoPost.monto = aNum(document.getElementById("ndMonto").value);
      if(!(cuerpoPost.monto > 0)){ toast("Poné el monto de la nota de débito."); document.getElementById("ndMonto").focus(); return; }
      if(!motivo){ toast("Poné el motivo de la nota de débito."); document.getElementById("notaMotivo").focus(); return; }
    }
    b.disabled = true;
    try{
      const r = await fetch(DOCS_URL + "/nota", { method:"POST", credentials:"same-origin", cache:"no-store",
        headers:{ "Content-Type":"application/json" }, body: JSON.stringify(cuerpoPost) });
      if(r.status === 401){ toast("Se cerró tu sesión: entrá de nuevo con tu usuario."); return; }
      const j = await r.json().catch(() => null);
      if(!j || j.error || !j.documento){ toast((j && j.error) || "No se pudo. Probá de nuevo."); return; }
      ponerStockServidor(j.stock);
      sumarNota(j.documento);
      cerrar();
      repintarInformes();
      pintarComprobantes();
      toast("Lista la " + j.documento.comp + " " + String(j.documento.nroTexto).replace(/^[AB] /, "") + " por " + fmt(j.documento.total) + "." + conCaeTxt(j.documento) +
        (nc ? " Lo devuelto volvió al stock." : ""));
    }catch(x){ toast("Sin conexión: probá de nuevo."); }
    finally{ if(document.body.contains(b)) b.disabled = false; }
  });
  const primero = fondo.querySelector(nc ? "[data-nc]" : "#ndMonto"); if(primero) primero.focus();
}
/** Debajo del vendedor: quién cobró (si no es el mismo) y quién despachó. */
function quienesCp(d){
  if(d.tipo === "presupuesto") return "";
  const cobro = d.cobroNombre || d.usuario || "";
  const dp = (d.datos || {}).despacho;
  const partes = [];
  if(cobro && plano(cobro) !== plano(d.vendedor || "")) partes.push("cobró " + txt(cobro));
  if(dp) partes.push("despachó " + txt(dp.nombre || dp.por));
  return partes.length ? '<small>' + partes.join(" · ") + '</small>' : "";
}
/** "Despachado": la mercadería salió del depósito, y queda quién la entregó. */
async function despacharDoc(d, boton, deshacer){
  if(deshacer && !confirm("¿Deshago el despacho de " + nombreDoc(d) + " " + numeroCorto(d) + "?")) return;
  boton.disabled = true;
  try{
    const r = await fetch(DOCS_URL + "/despachar", { method:"POST", credentials:"same-origin", cache:"no-store",
      headers:{ "Content-Type":"application/json" },
      body: JSON.stringify(Object.assign({ id:d.id, yo: soyYo() }, deshacer ? { deshacer:true } : {})) });
    if(r.status === 401){ toast("Se cerró tu sesión: entrá de nuevo con tu usuario."); return; }
    const x = await r.json().catch(() => null);
    if(!x || x.error || !x.documento){ toast("No se anotó: " + ((x && x.error) || "probá de nuevo.")); return; }
    const i = CP.docs.findIndex(y => y.id === d.id);
    if(i >= 0) CP.docs[i] = x.documento;
    pintarListaCp();
    toast(deshacer ? "Listo: quedó sin despachar." : "Anotado: lo despachaste vos.");
  }catch(e){ toast("No se anotó: revisá la conexión."); }
  finally{ boton.disabled = false; }
}

/** El detalle de un comprobante ya emitido, con el link a su PDF. */
function mandarPorWhats(d){
  const dt = d.datos || {}, cli = dt.cliente || {};
  abrirEnvio({
    quien: cli.n && cli.n !== "Consumidor final" ? cli.n : "",
    tit: nombreDoc(d),
    // abrirEnvio le saca la letra de adelante ("X 0006-..." -> "0006-...").
    nro: d.letra ? d.nroTexto : "- P-" + d.pedido,
    lineas: (dt.renglones || []).map(r => ({ p:{ tit:r.tit, contado:+r.contado || 0 }, cant:+r.cant || 0 })),
    total: d.total, senia: 0, url: d.link || "", suc: d.sucursal
  });
}

/** El usuario con el que se abrió esta página (lo puso el servidor). */
function soyYo(){
  return (typeof PUNTO_YO === "object" && PUNTO_YO && PUNTO_YO.usuario) ? String(PUNTO_YO.usuario) : "";
}

/** El nombre del archivo: "Presupuesto-0003-00003301.pdf". */
const nombrePdf = d => (nombreDoc(d) + " " + numeroCorto(d)).normalize("NFD").replace(/[̀-ͯ]/g, "")
  .replace(/[^A-Za-z0-9 _.-]/g, "").trim().replace(/\\s+/g, "-") + ".pdf";

/** Baja el PDF que arma el servidor, o lo manda a la impresora. */
async function traerPdf(d, boton, imprimir){
  if(boton) boton.disabled = true;
  try{
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), 30000);
    const r = await fetch(DOCS_URL + "/pdf?id=" + encodeURIComponent(d.id),
      { cache:"no-store", credentials:"same-origin", signal:ctl.signal });
    clearTimeout(t);
    if(r.status === 401){ toast("Se cerró tu sesión: entrá de nuevo con tu usuario."); return; }
    const tipo = r.headers.get("Content-Type") || "";
    if(!r.ok || tipo.indexOf("application/pdf") < 0){
      const j = await r.json().catch(() => null);
      toast((j && j.error) || "No pude armar el PDF. Probá de nuevo.");
      return;
    }
    const url = URL.createObjectURL(await r.blob());
    if(imprimir) mandarAImprimir(url);
    else {
      const a = document.createElement("a");
      a.href = url; a.download = nombrePdf(d);
      document.body.appendChild(a); a.click(); a.remove();
      toast("Bajando " + nombrePdf(d) + ".");
      setTimeout(() => URL.revokeObjectURL(url), 60000);
    }
  }catch(e){
    toast("No pude traer el PDF: revisá la conexión y probá de nuevo.");
  }finally{
    if(boton) boton.disabled = false;
  }
}
/** El PDF va a un marco escondido y de ahí a la impresora. Si el navegador
    no deja, se abre en otra pestaña para imprimirlo desde ahí. */
function mandarAImprimir(url){
  const viejo = document.getElementById("marcoImprimir");
  if(viejo) viejo.remove();
  const f = document.createElement("iframe");
  f.id = "marcoImprimir"; f.title = "Imprimir";
  f.style.cssText = "position:fixed;right:0;bottom:0;width:1px;height:1px;border:0;opacity:0";
  f.onload = () => {
    setTimeout(() => {
      try{ f.contentWindow.focus(); f.contentWindow.print(); }
      catch(e){ window.open(url, "_blank"); }
    }, 300);
  };
  f.src = url;
  document.body.appendChild(f);
  setTimeout(() => URL.revokeObjectURL(url), 10 * 60000);
}

/** Eliminar: sale de la lista y de la Caja, pero no se borra (queda en
    "Eliminados" y se recupera). Recuperar hace lo contrario. */
async function eliminarDoc(d, boton, recuperar){
  if(EMITIENDO){ toast("Esperá un segundo: se está guardando un comprobante."); return; }
  const nombre = nombreDoc(d) + " " + numeroCorto(d);
  if(!recuperar){
    const fiscal = d.tipo !== "presupuesto";
    if(!confirm("¿Eliminar " + nombre + " de " + d.cliente + " por " + fmt(d.total) + "?\\n\\n" +
      "Sale de la lista" + (fiscal ? " y de la Caja" : "") + ". No se borra del todo: queda en “Eliminados”, con tu usuario y la hora, y de ahí se recupera." +
      (fiscal ? " El número no se vuelve a usar." : ""))) return;
  }
  if(boton) boton.disabled = true;
  try{
    const r = await fetch(DOCS_URL + "/eliminar", {
      method:"POST", credentials:"same-origin", cache:"no-store",
      headers:{ "Content-Type":"application/json" },
      body: JSON.stringify({ id:d.id, recuperar:!!recuperar, yo: soyYo() })
    });
    if(r.status === 401){ toast("Se cerró tu sesión: entrá de nuevo con tu usuario."); return; }
    const j = await r.json().catch(() => null);
    if(!j || j.error || !j.documento){ toast((j && j.error) || "No se pudo. Probá de nuevo."); return; }
    ponerStockServidor(j.stock);
    // La Caja, la Rentabilidad y el Contable de esta pantalla.
    if(recuperar){
      if(j.documento.tipo === "nota-credito"){ if(esDeHoy(j.documento.createdAt)) sumarNota(j.documento); }
      else if(j.documento.tipo !== "presupuesto" && esDeHoy(j.documento.createdAt) && !S.ventas.some(v => v.docId === j.documento.id))
        S.ventas.push(ventaDeDocumento(j.documento));
    } else {
      S.ventas = S.ventas.filter(v => v.docId !== d.id);
      sacarNota(d.id);
    }
    if(S.editando && S.editando.id === d.id && !recuperar){
      terminarEdicion(); S.origen = null; pintarCamposVenta(); pintarTicket();
    }
    repintarInformes();
    const a = d.tipo === "factura" ? "a" : "o";   // la factura, el presupuesto
    toast(recuperar ? nombre + " recuperad" + a + ": vuelve a estar en la lista."
      : nombre + " eliminad" + a + ". Lo ves en “Eliminados” si hace falta recuperarl" + a + ".");
    CP.abierto = null;
    pintarComprobantes();
  }catch(e){
    toast("No se pudo: revisá la conexión y probá de nuevo.");
  }finally{
    if(boton) boton.disabled = false;
  }
}
/** ¿Es de hoy (en Argentina)? Lo de hoy es lo que está en la Caja. */
const esDeHoy = iso => fechaAR(iso) === fechaAR(new Date().toISOString());

/** Lo que vuelve de lo guardado: un presupuesto que se estaba cambiando. */
function editandoDe(x){
  if(!x || typeof x !== "object" || typeof x.id !== "string" || !/^[A-Za-z0-9_-]{8,40}$/.test(x.id)) return null;
  if(!SUCURSALES.some(s => s.id === x.suc)) return null;
  return { id:x.id, nro:String(x.nro || "").replace(/[<>&"']/g, "").slice(0, 20), base:Math.max(0, Math.floor(+x.base || 0)), suc:x.suc,
           sucAntes: SUCURSALES.some(s => s.id === x.sucAntes) ? x.sucAntes : null };
}
/** Se terminó de cambiar el presupuesto (se guardó, se facturó, se dejó):
    la venta vuelve a la sucursal en la que estaba antes de abrirlo. */
function terminarEdicion(){
  S.actualiza = null;
  const e = S.editando;
  S.editando = null;
  if(sucursalFija()){
    if(S.suc !== sucursalFija()){ S.suc = sucursalFija(); S.comp = null; S.dep = null; }
    const sel = document.getElementById("selSuc"); if(sel) sel.value = S.suc;
    return;
  }
  if(e && e.sucAntes && e.sucAntes !== S.suc && SUCURSALES.some(x => x.id === e.sucAntes)){
    S.suc = e.sucAntes; S.comp = null; S.dep = null;
    const sel = document.getElementById("selSuc");
    if(sel) sel.value = S.suc;
  }
}

/** El aviso arriba de los artículos mientras se cambia un presupuesto. */
function pintarEdicion(){
  const a = document.getElementById("avisoEdita");
  if(!a) return;
  if(!S.editando && S.actualiza){
    a.hidden = false;
    const hoy = S.linea.length ? armarDocumento("03.Presupuesto", "X").total : 0;
    a.innerHTML = '<span>↻</span><div><b>Estás rehaciendo el Presupuesto ' + txt(S.actualiza.nro) + ' a precios de hoy.</b> ' +
      'Antes ' + fmt(S.actualiza.total) + (hoy ? ', hoy ' + fmt(hoy) : '') + '. Al guardarlo sale un presupuesto nuevo, con otro número; el original queda como está. ' +
      '<button class="b3" type="button" id="btnNoEditar" style="padding:2px 9px;margin-left:4px">Dejar</button></div>';
    return;
  }
  if(!S.editando){ a.hidden = true; a.innerHTML = ""; return; }
  a.hidden = false;
  a.innerHTML = '<span>✎</span><div><b>Estás cambiando el Presupuesto ' + txt(S.editando.nro) + ' de ' + txt(sucDe(S.editando.suc).n) + '.</b> ' +
    'Sumá o sacá artículos y tocá <b>Guardar cambios</b>: sigue con el mismo número y lo de antes queda guardado. ' +
    'Si en cambio lo facturás, la venta queda unida a él. ' +
    '<button class="b3" type="button" id="btnNoEditar" style="padding:2px 9px;margin-left:4px">Dejar de editar</button></div>';
}
document.addEventListener("click", e => {
  if(!e.target.closest || !e.target.closest("#btnNoEditar")) return;
  if(EMITIENDO || trabadaPorDuda()) return;
  if(!confirm("¿Lo dejás? La venta de la pantalla se vacía y el presupuesto queda como estaba.")) return;
  S.linea = []; S.desc = 0; S.lista = 2; S.comp = null; S.dep = null; S.nroLibre = false;
  S.origen = null; S.emision = null; terminarEdicion();
  pintarCamposVenta(); pintarDtos(); pintarTicket(); guardarLocal();
});

/** Cambiar un presupuesto ya emitido: vuelve a la venta (a precio de hoy) y
    al guardarlo queda con el mismo número. */
function editarPresu(d){
  if(EMITIENDO){ toast("Esperá un segundo: se está guardando un comprobante."); return; }
  if(trabadaPorDuda()) return;
  if(!GBP.listo){ toast("Esperá un segundo: se están cargando los artículos."); return; }
  if(d.vendidoEn){ toast("Ese presupuesto ya se vendió: no se puede cambiar."); return; }
  if(sucursalFija() && sucursalFija() !== d.sucursal){ toast("Ese presupuesto es de " + sucDe(d.sucursal).n + ": tu usuario no puede cambiarlo."); return; }
  const ren = (d.datos && d.datos.renglones) || [];
  recuperarManuales(ren);
  const hay = ren.filter(r => prod(r.cod)), faltan = ren.length - hay.length;
  if(!hay.length){ toast("Ninguno de esos artículos está hoy en el catálogo."); return; }
  if(S.linea.length && !confirm("Hay una venta empezada. ¿La reemplazo por el presupuesto " + numeroCorto(d) + " para cambiarlo?")) return;
  S.linea = hay.map(r => ({ cod:r.cod, cant:Math.max(1, Math.floor(+r.cant || 1)) }));
  const cid = d.datos && d.datos.cliente && d.datos.cliente.id;
  const hayCliente = !!cid && CLIENTES.some(c => c.id === cid);
  S.cliente = hayCliente ? cid : "";
  S.desc = +(d.datos && d.datos.desc) || 0;
  const fo = d.datos && d.datos.forma;
  if(fo && MULT[fo]){ S.forma = fo; S.cond = fo; }
  // La sucursal del presupuesto: su número es de esa serie. Al terminar,
  // la venta vuelve a la de antes (terminarEdicion).
  terminarEdicion();
  const sucAntes = S.suc;
  if(SUCURSALES.some(x => x.id === d.sucursal)){ S.suc = d.sucursal; document.getElementById("selSuc").value = S.suc; }
  S.comp = null; S.dep = null; S.nroLibre = false;
  S.origen = d.id; S.emision = null;
  S.editando = { id:d.id, nro:numeroCorto(d), base:+(d.datos && d.datos.ed) || 0, suc:d.sucursal,
                 sucAntes: sucAntes !== d.sucursal ? sucAntes : null };
  abrirVista("mostrador");
  pintarCamposVenta(); pintarDtos(); pintarTicket();
  guardarLocal();
  const q = document.getElementById("q");
  q.value = ""; buscar(); q.focus();
  toast("Presupuesto " + numeroCorto(d) + " abierto para cambiarlo, con los precios de hoy." +
    (S.editando.sucAntes ? " La venta pasó a " + sucDe(d.sucursal).n + ", que es la del presupuesto; al terminar vuelve a " + sucDe(S.editando.sucAntes).n + "." : "") +
    (faltan ? " " + faltan + (faltan > 1 ? " artículos ya no están" : " artículo ya no está") + " en el catálogo y quedó afuera." : "") +
    (cid && !hayCliente ? " El cliente no está cargado en esta compu: elegilo de nuevo." : ""));
}

/** Lo guardado de "precios de hoy", revisado. */
function actualizaDe(x){
  if(!x || typeof x !== "object" || typeof x.id !== "string" || !/^[A-Za-z0-9_-]{8,40}$/.test(x.id)) return null;
  return { id:x.id, nro:String(x.nro || "").replace(/[<>&"']/g, "").slice(0, 20), total:+x.total || 0 };
}
/** Rehacer un presupuesto a precios de hoy: vuelve a la venta con los
    precios de ahora y, al guardarlo, sale uno nuevo unido al viejo. Si en
    cambio se factura, la venta queda unida al viejo (como Pasar a venta). */
function actualizarPresu(d){
  if(EMITIENDO){ toast("Esperá un segundo: se está guardando un comprobante."); return; }
  if(trabadaPorDuda()) return;
  if(!GBP.listo){ toast("Esperá un segundo: se están cargando los artículos."); return; }
  const ren = (d.datos && d.datos.renglones) || [];
  recuperarManuales(ren);
  const hay = ren.filter(r => prod(r.cod)), faltan = ren.length - hay.length;
  if(!hay.length){ toast("Ninguno de esos artículos está hoy en el catálogo."); return; }
  if(S.linea.length && !confirm("Hay una venta empezada. ¿La reemplazo por el presupuesto " + numeroCorto(d) + " a precios de hoy?")) return;
  terminarEdicion();
  S.linea = hay.map(r => ({ cod:r.cod, cant:Math.max(1, Math.floor(+r.cant || 1)) }));
  const cid = d.datos && d.datos.cliente && d.datos.cliente.id;
  const hayCliente = !!cid && CLIENTES.some(c => c.id === cid);
  S.cliente = hayCliente ? cid : "";
  S.desc = +(d.datos && d.datos.desc) || 0;
  const fo = d.datos && d.datos.forma;
  if(fo && MULT[fo]){ S.forma = fo; S.cond = fo; }
  S.comp = null; S.dep = null; S.nroLibre = false;
  S.origen = d.id; S.emision = null;
  S.actualiza = { id:d.id, nro:numeroCorto(d), total:+d.total || 0 };
  abrirVista("mostrador");
  pintarCamposVenta(); pintarDtos(); pintarTicket();
  guardarLocal();
  const hoy = armarDocumento("03.Presupuesto", "X").total;
  const dif = S.actualiza.total > 0 ? (hoy - S.actualiza.total) / S.actualiza.total * 100 : 0;
  toast("Presupuesto " + numeroCorto(d) + " a precios de hoy: antes " + fmt(S.actualiza.total) + ", hoy " + fmt(hoy) +
    " (" + (dif >= 0 ? "+" : "") + pTxt(Math.round(dif * 10) / 10) + "%)." +
    (faltan ? " " + faltan + (faltan > 1 ? " artículos ya no están" : " artículo ya no está") + " en el catálogo." : ""));
}

